    "explanation_dnat": "DNAT（送信先NAT）またはポートフォワーディングは、着信パケットの送信先IP/ポートを変更します。これにより、外部ユーザーがプライベートネットワーク内のサーバーにアクセスできます。",
    "explanation_nftables": "nftablesはiptablesのモダンな代替です。単一の'nft'ツールを使用し、IPv4とIPv6の両方を処理する'inet'テーブルをサポートします。NATルールは'nat'テーブルのフックとして追加され、通常はpreroutingに-100、postroutingに100の優先度で追加されます。",
    "explanation_default": "この設定は選択したプラットフォームに必要な構文を生成します。ほとんどのファイアウォールポリシーは上から下への実行順序に従います。",
