    "nat64": "NAT64 / DNS64",
    "nat64_desc": "IPv6のみのクライアントが変換経由でIPv4のみのサーバーと通信できるようにします。DNS64はAレコードからプレフィックスを使用してAAAAレコードを合成します。",
