    "ttl_desc": "パケットがこのスコープ境界を超えて転送されるために必要な最小TTL。ルーターは各スコープ境界でTTL閾値を適用します。",
    "glop_desc": "このアドレスはGLOPブロック（{rfc}）にあります。第2および第3オクテットが16ビットAS番号をエンコードします: {code}。各ASは/24のマルチキャスト空間を取得します。",
    "mac_desc": "IPから派生したレイヤ2アドレス。28ビットのうち23ビットのみがマッピング（プレフィックス{prefix}）、32の異なるIPがこのMACを共有します。",
