    "ref_reno_desc": "古典的な AIMD アルゴリズム。スロースタートは ssthresh まで RTT ごとに cwnd を 2 倍にします。輻輳回避は RTT ごとに約 1 セグメントを追加します。3 つの重複 ACK 時: ssthresh = cwnd/2、cwnd = ssthresh。タイムアウト時: cwnd = 1 MSS。公平ですが、損失後の高 BDP パスの利用率が低くなります。",
    "ref_cubic_desc": "Linux のデフォルト。三次関数 W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7) を使用します。損失後、cwnd は W_max の 70% に低下し、その後凹凸曲線を経て成長します。ロング・ファット・ネットワークにおいて Reno よりも積極的です。K = (W_max * 0.3 / C)^(1/3)。",
    "ref_bbr_desc": "Google のモデルベースアルゴリズム。損失を信号として使う代わりに、ボトルネック帯域幅と最小 RTT を推定します。フェーズ: Startup (2.89 倍のゲイン)、Drain、ProbeBW (8 フェーズのゲインサイクル: 1.25/0.75/1...)、ProbeRTT (約 10 秒ごとに 4 セグメント)。損失があってもフルスループットを達成します。",
