    "plat_iosxr_notes": "IOS-XR のファイルシステムは flash: の代わりに disk0: または disk1: を使用します。XR の SCP/SFTP コマンドはユーザーパスワードを対話的に要求します。ルーティングコンテキスト（VRF）はグローバルに設定できます。",
    "plat_nxos_notes": "NX-OS はデフォルトで bootflash: を使用します。\"dir bootflash:\" でファイルシステムの容量を確認してください。VRF からサーバーへの IP 到達性が必要です。デフォルトルーティングまたは管理 VRF を確認してください。",
    "plat_junos_notes": "Junos でのファイルコピーは /var/tmp/ または /var/db/config/ に配置されます。\"show system storage\" でディスク容量を確認してください。TFTP 転送には Junos のルーティングプロトコル設定または routing-instance キーワードの使用が必要な場合があります。",
    "plat_eos_notes": "Arista 機器は flash: を使用します。\"dir flash:\" で確認してください。高スループットのために、Arista は高度に最適化されたネイティブの HTTP/HTTPS コピーをサポートしています。",
    "plat_fortios_notes": "FortiOS の TFTP リストアはブートイメージを置き換え、デバイスを自動的に再起動します。注意して使用してください。必ず事前に設定ファイルを保存してください。",
    "plat_panos_notes": "Palo Alto PAN-OS でソフトウェアのインポートコマンドを実行するには、明示的な CLI 管理者権限が必要です。ソフトウェアは Palo Alto の公式サポートアップデートから直接ダウンロードすることもできます。",
    "plat_linux_notes": "ターゲットディレクトリの読み取り/書き込み権限を確認してください。クライアント（scp、curl）がインストールされていることを確認してください。curl/wget による HTTP/HTTPS 転送は高い並列化が可能です。",
    "plat_f5_notes": "bigstart プロセスと F5 の管理ルート権限を確認してください。宛先フォルダー /shared/images/ は F5 ISO ファイルのデフォルトの場所です。",
    "cmd_iosxe": "! Cisco IOS/IOS-XE コマンド",
    "cmd_iosxr_scp": "! Cisco IOS-XR コマンド（注意：scp/sftp クライアントには ssh クライアントの設定が必要）",
    "cmd_iosxr": "! Cisco IOS-XR コマンド",
    "cmd_nxos": "! Cisco NX-OS コマンド",
    "cmd_junos": "# Juniper Junos コマンド",
    "cmd_junos_tftp": "# Juniper Junos コマンド（tftp fetch にはシェルアクセスまたは ftp/http が必要）",
    "cmd_eos": "! Arista EOS コマンド",
    "cmd_fortios_restore": "# FortiOS コマンド（ファームウェア復元）",
    "cmd_fortios_note": "# FortiOS のファームウェア更新は通常、HTTPS / FortiGuard またはローカルの GUI アップロードで行われます。",
    "cmd_linux": "# Linux コマンド",
    "cmd_linux_note": "# Linux サーバーには SCP/SFTP または HTTP/HTTPS を推奨します。",
