    "scenario_overlap_desc": "2 つのネットワークが同じプライベート範囲（例: 192.168.1.0/24）を使用しています。IP 競合なしで通信するには、両側で NAT を実行する必要があります。ホスト A はトランジット IP に変換され、ホスト B もトランジット IP に変換されます。",
    "scenario_cgnat_title": "シナリオ 2: キャリアグレード NAT (CGNAT) からカスタマー NAT",
    "scenario_cgnat_desc": "サービスプロバイダーはカスタマー WAN に 100.64.0.0/10 (RFC 6598) を割り当てます。カスタマーはローカル NAT (192.168.1.0/24 -> 100.64.1.2) を実行し、プロバイダーは IPv4 スペースを節約するために CGNAT (100.64.1.2 -> パブリック IP) を実行します。",
