    "err_invalid_global": "インサイドグローバル サブネットまたは範囲の形式が無効です",
    "err_invalid_ip": "IP アドレスの形式が無効です",
    "explanation_title": "NAT と PAT の違いを理解する",
    "explanation_intro": "ネットワークアドレス変換 (NAT) とポートアドレス変換 (PAT) は、IP アドレス空間を別の空間にマッピングする手法であり、主に限られたパブリック IPv4 アドレスを節約したり、サブネットの競合を解決したりするために使用されます。",
    "nat_expl_title": "1. NAT とは？",
    "nat_expl_desc": "NAT は IP アドレスを 1 対 1 で変換します。スタティック（1 つのプライベート IP を 1 つのパブリック IP に恒久的にマッピング、公開サーバーに最適）またはダイナミック（必要に応じてプールからプライベートホストにパブリック IP を割り当てる。すべてのパブリック IP が割り当てられると、IP が解放されるまで後続のホストはブロックされる）があります。ポート番号は変更されません。",
    "pat_expl_title": "2. PAT (NAT オーバーロード) とは？",
    "pat_expl_desc": "PAT（またはポートアドレス変換 / NAT オーバーロード）は、IP アドレスと送信元ポート番号の両方を多対 1 (N 対 1) で変換します。一意の送信元ポートを割り当てることで、複数のプライベートホストが単一のパブリック IP アドレスを共有します（例: 192.168.1.10:5000 と 192.168.1.11:5000 を 203.0.113.10:1024 と 203.0.113.10:1025 にマッピング）。これはホームルーターや企業のインターネットアクセスにおける標準的な方法です。",
    "comparison_table_title": "比較のまとめ",
    "comp_header_feature": "機能",
    "comp_header_nat": "NAT（1 対 1）",
    "comp_header_pat": "PAT（N 対 1 / オーバーロード）",
    "comp_row_ratio": "IP アドレス比率",
