    "about_body": "iperfは、IPネットワーク上で達成可能な最大帯域幅をアクティブに測定するためのツールです。一方のホストがサーバー（リスナー）として動作し、もう一方がクライアントとして接続してTCP、UDP、またはSCTPでトラフィックを送信（または受信）し、スループット、ジッター、パケット損失を報告します。iperf3（バイナリ名 iperf3）はJSON出力やリバース/双方向モードを備えたモダンな書き直し版です。iperf2（バイナリ名 iperf）はマルチクライアント対応で、Wi-Fiやマルチキャストのテストに強力です。両者は通信互換性がありません。両端で同じバージョンを実行する必要があります。",
