    "note_1": "iperf3は一度に1つのクライアントしか処理できません。並行テストを行う場合は、異なるポートで複数のiperf3インスタンスを実行してください。",
    "note_2": "制御トラフィックとデータトラフィックは同じポート（iperf3はデフォルト5201、iperf2は5001）を使用します。ファイアウォールでそのポートのTCPとUDPの両方を開放してください。",
    "note_3": "UDPテストには明示的な-b帯域幅ターゲットが必要です。指定しない場合、iperf2とiperf3は共にデフォルトで1 Mbit/sになります。",
    "note_4": "iperf2とiperf3は互換性がありません。クライアントとサーバーは同じメジャーバージョンを実行する必要があります。",
    "note_5": "高BDP（広帯域遅延積）の経路では、-wでソケットウィンドウを増やし（例：-w 4M）、-Pで複数のストリームを使用してリンクを飽和させてください。",
